widget.solution:
#include <iostream>
#include <string>

class Logger {
public:
    explicit Logger(const std::string& name) : name_(name) {
        std::cout << "open " << name_ << '\n';
    }
    ~Logger() { std::cout << "close " << name_ << '\n'; }
private:
    std::string name_;
};

int main() {
    std::string x, y, z;
    std::cin >> x >> y >> z;
    Logger first(x);
    {
        Logger second(y);
        std::cout << "work\n";
    }
    Logger third(z);
}

