widget.solution:
#include <vector>

class Buffer {
public:
    Buffer(int n, double x) : data_(n, x) {}
    Buffer(const Buffer&) = default;
    Buffer(Buffer&&) = default;
    Buffer& operator=(const Buffer&) = default;
    Buffer& operator=(Buffer&&) = default;

    int size() const { return static_cast<int>(data_.size()); }
    double get(int i) const { return data_[i]; }
    void set(int i, double x) { data_[i] = x; }

private:
    std::vector<double> data_;
};

widget.postlude:
#include <type_traits>
#include <utility>
// Hidden helpers: assign into an existing Buffer, only when the class allows it (-1 otherwise)
template <class B> double copied_into_existing() {
    if constexpr (std::is_copy_assignable_v<B>) {
        B a(3, 1.5);
        B b(1, 0.0);
        b = a;
        b.set(0, 9.0);
        return a.get(0) + b.get(0);
    } else return -1;
}
template <class B> double moved_into_existing() {
    if constexpr (std::is_move_assignable_v<B>) {
        B a(3, 1.5);
        B c(1, 0.0);
        c = std::move(a);
        return a.size() + 10 * c.size();
    } else return -1;
}

