    std::string venue() const { return venue_; }

private:
    std::string venue_;
    bool open_;
};

widget.solution:
#include <string>
#include <utility>

// disconnect(venue) is provided: call it once per open connection.

class Connection {
public:
    explicit Connection(const std::string& venue) : venue_(venue), open_(true) {}

    ~Connection() {
        if (open_) disconnect(venue_);
    }
    Connection(const Connection&) = delete;
    Connection& operator=(const Connection&) = delete;
    Connection(Connection&& other) noexcept
        : venue_(std::move(other.venue_)), open_(other.open_) {
        other.open_ = false;
    }

    bool is_open() const { return open_; }
    std::string venue() const { return venue_; }

private:
    std::string venue_;
    bool open_;
};

